{
  "themes": [
    {
      "cluster": 12,
      "name": "Login And Account Access Issues",
      "description": "Customers cannot log in or access their accounts and request help resetting or recovering them."
    },
    {
      "cluster": 13,
      "name": "Disabled Account Reactivation Requests",
      "description": "Users report their accounts being disabled and ask for reasons and how to restore access."
    },
    {
      "cluster": 14,
      "name": "Unclear Error Messages And URLs",
      "description": "Customers receive cryptic error messages or broken URLs and seek explanations or fixes."
    },
    {
      "cluster": 15,
      "name": "Perceived Service Jokes And Frustration",
      "description": "Feedback expresses disbelief that the service is a joke, demanding answers to odd or rude messages."
    },
    {
      "cluster": 16,
      "name": "Direct Message (DM) Follow‑Up Requests",
      "description": "Users mention having sent a DM and ask the team to check or reply to it."
    },
    {
      "cluster": 17,
      "name": "Negative Customer Service Experience",
      "description": "Customers complain that support is poor, unresponsive, or outright terrible."
    },
    {
      "cluster": 18,
      "name": "Urgent Need For Real Contact Channels",
      "description": "Users request phone numbers, email, or other direct contact methods for immediate assistance."
    },
    {
      "cluster": 19,
      "name": "Worst‑Case Support Feedback",
      "description": "Feedback labels the support system as the worst, highlighting severe dissatisfaction."
    },
    {
      "cluster": 20,
      "name": "Missing Phone Support Number",
      "description": "Customers specifically ask for a phone number to reach support, noting its absence."
    },
    {
      "cluster": 21,
      "name": "Credit Card And Uber Credit Payment Problems",
      "description": "Users report that credit cards or Uber credits are rejected or not applied to rides."
    },
    {
      "cluster": 22,
      "name": "Unexpected Charges And Refund Requests",
      "description": "Customers see extra or duplicate charges on their accounts and seek refunds or explanations."
    },
    {
      "cluster": 23,
      "name": "Payment Method Errors With Specific Cards",
      "description": "Feedback describes payment failures using particular cards or cash, often with error messages."
    }
  ]
}
